   DT(D, "Où arrive la First Fleet ?", ["À Sydney", "À Melbourne", "À Perth", "À Canberra"]),
   DT(D, "Comment s'appelle le célèbre rocher sacré ?", ["Uluru", "Waitangi", "Kakadu", "Ayers Bay"]),
